import { describe, expect, it } from "vitest";
import type { ScoreDocumentPort } from "../score/document";
import type { LoadedAudio } from "./types";
import {
  buildProjectDocument,
  deriveProjectId,
  isSaveableRevision,
} from "./project";

function fakeDoc(overrides: Partial<ScoreDocumentPort> = {}): ScoreDocumentPort {
  return {
    revisionId: "rev-0123456789abcdef",
    editVersion: 0,
    meta: {
      title: "t",
      tempoBpm: 120,
      meter: "4/4",
      keyFifths: 0,
      keyChanges: [],
      measureCount: 1,
      noteCount: 1,
    },
    musicXml: () => "<xml/>",
    reviewIssues: () => [],
    recordReviewDecision: () => undefined,
    noteEdits: () => new Map(),
    setNoteEdit: () => undefined,
    ...overrides,
  };
}

function fakeAudio(): LoadedAudio {
  return {
    ref: { kind: "path", path: "C:\\audio\\take.wav", name: "take.wav" },
    fileName: "take.wav",
    format: "wav",
    sizeBytes: 100,
    durationSeconds: 5,
    sampleRate: 44100,
    peaks: [0.5],
    mediaSource: { kind: "blob", blob: new Blob() },
  };
}

const RESULT = {
  scoreRevision: "rev-0123456789abcdef",
  scoreDocument: { notes: [] },
  reviewIssues: [],
  meta: {
    backend: "basic_pitch",
    backendVersion: "0.4.0",
    transcriptionRevision: "tr-0123456789abcdef",
    settings: { tempoBpm: 120 },
  },
};

describe("deriveProjectId", () => {
  it("produces a stable prj- id", async () => {
    const a = await deriveProjectId({ x: 1, y: "z" });
    const b = await deriveProjectId({ x: 1, y: "z" });
    expect(a).toBe(b);
    expect(a).toMatch(/^prj-[0-9a-f]{16}$/);
  });
});

describe("isSaveableRevision", () => {
  it("accepts engine revisions, rejects fixture ids", () => {
    expect(isSaveableRevision("rev-0123456789abcdef")).toBe(true);
    expect(isSaveableRevision("rev-fixture0000001")).toBe(false);
    expect(isSaveableRevision("sr-0001")).toBe(false);
  });
});

describe("buildProjectDocument", () => {
  it("assembles a schema-v1 document", async () => {
    const doc = await buildProjectDocument({
      audio: fakeAudio(),
      doc: fakeDoc(),
      result: RESULT,
    });
    expect(doc).not.toBeNull();
    expect(doc!.schemaVersion).toBe(1);
    expect(doc!.projectId).toMatch(/^prj-/);
    expect(doc!.sourceAudio).toEqual({
      originalPath: "C:\\audio\\take.wav",
      contentHash: "",
    });
    expect(doc!.transcription).toMatchObject({
      backend: "basic_pitch",
      revision: "tr-0123456789abcdef",
    });
    expect(doc!.score).toMatchObject({ revision: "rev-0123456789abcdef" });
    expect(doc!.musicXmlConcert).toBe("<xml/>");
  });

  it("returns null for a non-schema (fixture) revision", async () => {
    const doc = await buildProjectDocument({
      audio: fakeAudio(),
      doc: fakeDoc({ revisionId: "rev-fixture0000001" }),
      result: RESULT,
    });
    expect(doc).toBeNull();
  });

  it("maps note edits and review decisions", async () => {
    const doc = await buildProjectDocument({
      audio: null,
      doc: fakeDoc({
        noteEdits: () =>
          new Map([["sn-000003", { pitchDelta: 1, deleted: true }]]),
        reviewIssues: () => [
          {
            id: "ri-1",
            scoreRevision: "rev-0123456789abcdef",
            canonicalNoteIds: ["sn-000003"],
            reason: "other",
            severity: "info",
            evidence: {},
            status: "accepted",
          },
        ],
      }),
      result: RESULT,
    });
    const edits = doc!.userEdits as { kind: string }[];
    expect(edits.map((e) => e.kind)).toEqual(["pitch_change", "delete"]);
    const decisions = doc!.reviewDecisions as { status: string }[];
    expect(decisions).toHaveLength(1);
    expect(decisions[0].status).toBe("accepted");
    expect(doc!.sourceAudio).toBeNull();
  });

  it("#115: saves the live canonical payload, not the stale job result", async () => {
    // After an engine rhythm edit the document's scoreDocument is newer
    // than the completed job's — the project must carry the live one or
    // the edit is lost on reopen.
    const live = { content: { parts: [{ notes: [{ id: "sn-000001" }] }] } };
    const doc = await buildProjectDocument({
      audio: null,
      doc: fakeDoc({ canonicalDocument: () => live }),
      result: RESULT,
    });
    expect(doc!.scoreDocument).toBe(live);
    // A document without the canonical payload falls back to the result's.
    const docNoCanon = await buildProjectDocument({
      audio: null,
      doc: fakeDoc(),
      result: RESULT,
    });
    expect(docNoCanon!.scoreDocument).toEqual({ notes: [] });
  });
});

/**
 * ScoreDocumentPort — the typed seam between the score workspace and the
 * score source (UI-030).
 *
 * Today the only implementation is the deterministic fixture adapter
 * (`fixtureDocument.ts`). When the engine pipeline lands (UI-040+), a real
 * adapter supplies the same shape — canonical MusicXML per presentation,
 * review issues, document meta — and the workspace needs no changes.
 *
 * Contract notes (FND-001 / ids.py):
 * - `musicXml("concert")` is the canonical sounding document;
 *   `musicXml("hornF")` is the written-pitch F管 presentation of the SAME
 *   canonical notes — identical `hs-sn-*` element ids in both.
 * - `reviewIssues()` mirrors `ReviewIssue.to_dict()` (domain/review.py).
 */
import type { PitchViewSetting } from "../commands/types";
import type { ReviewIssueStatus, ScoreReviewIssue } from "./review";
import type { ScoreNoteEdit } from "./scoreEdits";

export interface ScoreDocumentMeta {
  /** Document title (MusicXML movement/work title). */
  readonly title: string;
  /** Tempo from `<sound tempo>` / score tempo map, beats per minute. */
  readonly tempoBpm: number | null;
  /** Time signature "4/4" style, when notated. */
  readonly meter: string | null;
  /** Key signature fifths (−7…+7), when notated. */
  readonly keyFifths: number | null;
  /** #146: key changes with measure numbers (head first); empty or
   *  single-entry = the piece stays in keyFifths. */
  readonly keyChanges: readonly { measure: number; fifths: number }[];
  /** Number of measures in the score. */
  readonly measureCount: number;
  /** Number of canonical `sn-*` notes (rests excluded). */
  readonly noteCount: number;
}

export interface ScoreDocumentPort {
  /** `rev-<sha256[:16]>` — content-derived score revision id. A new
   *  transcription/quantization produces a new revision; review decisions
   *  and note edits are bound to it and never silently carried across
   *  (domain/review.py contract). */
  readonly revisionId: string;
  /** Bumped on every user edit/decision so views can invalidate. */
  readonly editVersion: number;
  readonly meta: ScoreDocumentMeta;
  /** MusicXML 4.0 string for the given pitch presentation — includes any
   *  user note edits (UI-050), so export sees the corrected document. */
  musicXml(view: PitchViewSetting): string;
  /** Review issues for this score revision (any status), with user
   *  decisions recorded via `recordReviewDecision` already applied. */
  reviewIssues(): readonly ScoreReviewIssue[];
  /**
   * Persist a review decision against (issueId, this revision) — the
   * document-model record the project-file adapter will later serialize.
   */
  recordReviewDecision(issueId: string, status: ReviewIssueStatus): void;
  /** Current canonical-note edits (`sn-*` id → edit). */
  noteEdits(): ReadonlyMap<string, ScoreNoteEdit>;
  /** Set or clear (`null` / empty edit) a canonical note's correction. */
  setNoteEdit(canonicalId: string, edit: ScoreNoteEdit | null): void;

  /* ---- #115 (spec 13): rhythm edits via the engine ----
   * These three are optional: only engine-backed documents can rebuild
   * notation. The workspace gates rhythm edits on a non-null
   * canonicalDocument() — a document without the canonical payload
   * (fixtures, dev) has nothing to send to score.edit, so the edit
   * stays unavailable (honest, never faked). */
  /** The canonical scoreDocument dict (schema v1 content) the engine's
   *  `score.edit` needs as its base, or null for non-engine sources. */
  canonicalDocument?(): unknown | null;
  /** The current XML bodies + revision — the undo-stack snapshot for
   *  engine-driven content swaps. */
  contentSnapshot?(): {
    concertXml: string;
    hornXml: string;
    revisionId: string;
    canonicalDocument: unknown;
  };
  /** Swap the document's content in place (engine rhythm edit): same
   *  object, new bodies + revision + meta. The workspace re-renders via
   *  editVersion — selection and the undo stack survive, unlike a
   *  remount. */
  replaceContent?(next: {
    concertXml: string;
    hornXml: string;
    revisionId: string;
    canonicalDocument: unknown;
  }): void;
}

/**
 * Inspector view-model tests (UI-030). All Japanese text is produced in
 * score/inspector.ts via a copy deck — these tests pin the model shape the
 * PropertiesPanel renders.
 */
import { describe, expect, it } from "vitest";
import {
  buildNoteInspector,
  buildScoreInspector,
  headlinePitch,
  keyLabelJa,
  type InspectorCopy,
} from "./inspector";
import type { ParsedNote } from "./scoreDoc";
import type { ScoreReviewIssue } from "./review";

const copy: InspectorCopy = {
  review: {
    reasonTitle: (r) => `title:${r}`,
    reasonDetail: (i) => `detail:${i.reason}`,
    severityLabel: (s) => `sev:${s}`,
    statusLabel: (s) => `status:${s}`,
  },
  measure: (n) => `第${n}小節`,
  scoreSeconds: (sec) => `スコア ${sec.toFixed(1)} 秒`,
  tieFragments: (n) => `タイで分割（${n}分割）`,
  tempo: (bpm) => `${bpm} BPM`,
  measureCount: (n) => `${n} 小節`,
  noteCount: (n) => `${n} 音`,
  openIssues: (n) => `${n} 件`,
  key: (fifths) => keyLabelJa(fifths),
};

const note = (over: Partial<ParsedNote>): ParsedNote => ({
  exportId: "hs-sn-000001",
  canonicalId: "sn-000001",
  isRest: false,
  chord: false,
  measure: 1,
  dots: 0,
  tied: false,
  ...over,
});

describe("buildScoreInspector", () => {
  it("summarizes the document for the nothing-selected state", () => {
    const model = buildScoreInspector(
      {
        title: "Test Piece",
        tempoBpm: 100,
        meter: "4/4",
        keyFifths: -1,
        keyChanges: [],
        measureCount: 12,
        noteCount: 40,
      },
      3,
      copy,
    );
    expect(model.kind).toBe("score");
    expect(model.tempoLabel).toBe("100 BPM");
    expect(model.meterLabel).toBe("4/4");
    expect(model.keyLabel).toBe("ヘ長調");
    expect(model.measureLabel).toBe("12 小節");
    expect(model.noteLabel).toBe("40 音");
    expect(model.openIssueLabel).toBe("3 件");
  });

  it("shows key transitions when the piece modulates (#146)", () => {
    const model = buildScoreInspector(
      {
        title: "Modulating Piece",
        tempoBpm: 100,
        meter: "4/4",
        keyFifths: 0,
        keyChanges: [
          { measure: 1, fifths: 0 },
          { measure: 17, fifths: -5 },
        ],
        measureCount: 32,
        noteCount: 100,
      },
      0,
      copy,
    );
    expect(model.keyLabel).toBe("ハ長調 → 変ニ長調（第17小節）");
  });
});

describe("buildNoteInspector", () => {
  const concert = [
    note({ exportId: "hs-sn-000012", canonicalId: "sn-000012", step: "C", octave: 4, type: "quarter", measure: 4 }),
    note({ exportId: "hs-sn-000012-2", canonicalId: "sn-000012", step: "C", octave: 4, type: "whole", measure: 5, tied: true }),
  ];
  const written = [
    note({ exportId: "hs-sn-000012", canonicalId: "sn-000012", step: "G", octave: 4, type: "quarter", measure: 4 }),
    note({ exportId: "hs-sn-000012-2", canonicalId: "sn-000012", step: "G", octave: 4, type: "whole", measure: 5, tied: true }),
  ];
  const issues: ScoreReviewIssue[] = [
    {
      id: "ri-000001",
      scoreRevision: "rev-x",
      canonicalNoteIds: ["sn-000012"],
      reason: "quantization_ambiguous",
      severity: "caution",
      evidence: { confidence: 0.713 },
      status: "open",
    },
  ];

  it("builds the note-selected model with both presentations", () => {
    const model = buildNoteInspector({
      canonicalId: "sn-000012",
      concert,
      written,
      onsetMs: 7200,
      issues,
      copy,
    });
    expect(model.kind).toBe("note");
    expect(model.canonicalId).toBe("sn-000012");
    expect(model.concertPitch).toBe("C4");
    expect(model.writtenPitch).toBe("G4");
    expect(model.measure).toBe(4);
    expect(model.onsetLabel).toBe("第4小節（スコア 7.2 秒）");
    expect(model.tieLabel).toBe("タイで分割（2分割）");
    expect(model.issues[0]?.reasonTitle).toBe("title:quantization_ambiguous");
    expect(model.issues[0]?.confidencePct).toBe(71);
  });

  it("omits the written row when both presentations spell the same", () => {
    const model = buildNoteInspector({
      canonicalId: "sn-000001",
      concert: [note({ step: "C", octave: 4 })],
      written: [note({ step: "C", octave: 4 })],
      onsetMs: null,
      issues: [],
      copy,
    });
    expect(model.writtenPitch).toBeNull();
    expect(model.tieLabel).toBeNull();
  });

  it("handles rests (no canonical id, no issues)", () => {
    const model = buildNoteInspector({
      canonicalId: null,
      concert: [note({ canonicalId: null, isRest: true, exportId: "hs-rest-000001" })],
      written: [],
      onsetMs: null,
      issues: [],
      copy,
    });
    expect(model.canonicalId).toBeNull();
    expect(model.concertPitch).toBe("");
  });
});

describe("headlinePitch", () => {
  const model = buildNoteInspector({
    canonicalId: "sn-000012",
    concert: [note({ step: "C", octave: 4 })],
    written: [note({ step: "G", octave: 4 })],
    onsetMs: null,
    issues: [],
    copy,
  });

  it("leads with the presentation the user is viewing", () => {
    expect(headlinePitch(model, "concert").primary).toBe("C4");
    expect(headlinePitch(model, "hornF").primary).toBe("G4");
    expect(headlinePitch(model, "hornF").secondary).toBe("C4");
  });
});

describe("keyLabelJa", () => {
  it("maps fifths to Japanese key names", () => {
    expect(keyLabelJa(0)).toBe("ハ長調");
    expect(keyLabelJa(-1)).toBe("ヘ長調");
    expect(keyLabelJa(1)).toBe("ト長調");
    expect(keyLabelJa(42)).toBe("42");
  });
});

/**
 * Inspector contract (UI-030) — the view-model bridge between the score
 * workspace and the properties panel (GUI_UX_PLAN §22: the inspector body
 * changes with the selection context).
 *
 * The workspace builds an `InspectorModel`; `PropertiesPanel` renders it.
 * All Japanese text is produced HERE so the panel stays a dumb renderer and
 * the copy stays testable in one place.
 *
 * Contexts (§22):
 *   - note selected → pitch (written/concert), onset, duration, review info
 *   - nothing selected → score/measure summary
 *   - time range selected → reserved for the waveform range path (UI-020+)
 */
import type { ScoreDocumentMeta } from "./document";
import type { ScoreReviewIssue } from "./review";
import { issueConfidence } from "./review";
import { noteTypeJa, pitchLabel, type ParsedNote } from "./scoreDoc";
import type { PitchViewSetting } from "../commands/types";

export interface InspectorIssueRow {
  readonly id: string;
  /** Japanese reason title (copy deck mapping in ja.ts). */
  readonly reasonTitle: string;
  readonly reasonDetail: string;
  readonly severityLabel: string;
  readonly statusLabel: string;
  /** 0–100 integer percent, when the issue carries confidence evidence. */
  readonly confidencePct: number | null;
}

export interface NoteInspectorModel {
  readonly kind: "note";
  /** Canonical `sn-*` id — the only identity shown to the user.
   *  `null` for rests (presentation-only `hs-rest-*` ids). */
  readonly canonicalId: string | null;
  /** Measure number (1-based) of the first fragment. */
  readonly measure: number;
  /** Concert-pitch label, e.g. "B♭3" — always shown (canonical truth). */
  readonly concertPitch: string;
  /** Written F管 label, e.g. "F4" — shown when it differs ( horn view / info ). */
  readonly writtenPitch: string | null;
  /** Japanese duration label, e.g. "付点四分音符". */
  readonly durationLabel: string;
  /** Onset inside the score, e.g. "第3小節（スコア 7.2 秒）". */
  readonly onsetLabel: string;
  /** Tie-fragment note, e.g. "タイで分割（3分割）". */
  readonly tieLabel: string | null;
  readonly issues: readonly InspectorIssueRow[];
}

export interface ScoreInspectorModel {
  readonly kind: "score";
  readonly title: string;
  readonly tempoLabel: string | null;
  /** Raw tempo for the editable BPM field (#115 setTempo). */
  readonly tempoBpm: number | null;
  readonly meterLabel: string | null;
  /** Raw meter for the editable field (#129 setMeter), parsed from the
   *  "n/m" label — null when the score carries no usable signature. */
  readonly meterBeats: number | null;
  readonly meterUnit: number | null;
  readonly keyLabel: string | null;
  readonly measureLabel: string;
  readonly noteLabel: string;
  readonly openIssueLabel: string;
}

export interface RangeInspectorModel {
  readonly kind: "range";
  readonly startLabel: string;
  readonly endLabel: string;
}

/** No score loaded — panel placeholder (EMPTY/AUDIO_READY/TRANSCRIBING). */
export interface EmptyInspectorModel {
  readonly kind: "empty";
}

export type InspectorModel =
  | NoteInspectorModel
  | ScoreInspectorModel
  | RangeInspectorModel
  | EmptyInspectorModel;

export interface ReviewCopy {
  reasonTitle(reason: ScoreReviewIssue["reason"]): string;
  /** Detail may look at the issue's evidence (counts, ranges) — the
   *  copy layer decides what is safe to surface. */
  reasonDetail(issue: ScoreReviewIssue): string;
  severityLabel(severity: ScoreReviewIssue["severity"]): string;
  statusLabel(status: ScoreReviewIssue["status"]): string;
}

export interface InspectorCopy {
  readonly review: ReviewCopy;
  /** e.g. (n) => `第${n}小節` */
  measure(n: number): string;
  /** e.g. (sec) => `スコア ${sec} 秒` */
  scoreSeconds(sec: number): string;
  /** e.g. (n) => `タイで分割（${n}分割）` */
  tieFragments(count: number): string;
  /** e.g. (bpm) => `${bpm} BPM` */
  tempo(bpm: number): string;
  /** e.g. (n) => `${n} 小節` */
  measureCount(n: number): string;
  /** e.g. (n) => `${n} 音` */
  noteCount(n: number): string;
  /** e.g. (n) => `要確認 ${n} 件` */
  openIssues(n: number): string;
  /** Key-signature label for fifths (e.g. `ヘ長調`/`変ロ長調`…). */
  key(fifths: number): string;
}

const FIFTHS_JA: Record<string, string> = {
  "-7": "変ハ長調",
  "-6": "変ト長調",
  "-5": "変ニ長調",
  "-4": "変イ長調",
  "-3": "変ホ長調",
  "-2": "変ロ長調",
  "-1": "ヘ長調",
  "0": "ハ長調",
  "1": "ト長調",
  "2": "ニ長調",
  "3": "イ長調",
  "4": "ホ長調",
  "5": "ロ長調",
  "6": "嬰ヘ長調",
  "7": "嬰ハ長調",
};

export function keyLabelJa(fifths: number): string {
  return FIFTHS_JA[String(fifths)] ?? `${fifths}`;
}

/** Parse a "n/m" meter label into raw signature parts (#129). */
export function parseMeterLabel(
  label: string | null,
): { beats: number; unit: number } | null {
  if (!label) return null;
  const m = /^(\d+)\s*\/\s*(\d+)$/.exec(label.trim());
  if (!m) return null;
  const beats = Number(m[1]);
  const unit = Number(m[2]);
  if (!Number.isSafeInteger(beats) || !Number.isSafeInteger(unit)) return null;
  return { beats, unit };
}

/** Nothing-selected summary (§22 "Nothing selected" → project/score info). */
export function buildScoreInspector(
  meta: ScoreDocumentMeta,
  openIssueCount: number,
  copy: InspectorCopy,
): ScoreInspectorModel {
  const meter = parseMeterLabel(meta.meter);
  return {
    kind: "score",
    title: meta.title,
    tempoLabel: meta.tempoBpm != null ? copy.tempo(meta.tempoBpm) : null,
    tempoBpm: meta.tempoBpm,
    meterLabel: meta.meter,
    meterBeats: meter?.beats ?? null,
    meterUnit: meter?.unit ?? null,
    // #146: with mid-piece key changes, show the transitions
    // (head key -> key at measure N) instead of just the head key.
    keyLabel:
      meta.keyChanges.length > 1
        ? meta.keyChanges
            .map((c, i) =>
              i === 0
                ? copy.key(c.fifths)
                : copy.key(c.fifths) + "（第" + c.measure + "小節）",
            )
            .join(" → ")
        : meta.keyFifths != null
          ? copy.key(meta.keyFifths)
          : null,
    measureLabel: copy.measureCount(meta.measureCount),
    noteLabel: copy.noteCount(meta.noteCount),
    openIssueLabel: copy.openIssues(openIssueCount),
  };
}

/**
 * Note-selected body (§22 "Note selected").
 *
 * `concert` / `written` are the parsed fragments of the SAME canonical note
 * in each presentation (from `notesByCanonical` of each document). The
 * written row is shown whenever the F管 presentation spells it differently,
 * so switching views never loses the context the user was reading.
 */
export function buildNoteInspector(args: {
  canonicalId: string | null;
  concert: readonly ParsedNote[];
  written: readonly ParsedNote[];
  onsetMs: number | null;
  issues: readonly ScoreReviewIssue[];
  copy: InspectorCopy;
}): NoteInspectorModel {
  const { canonicalId, concert, written, onsetMs, issues, copy } = args;
  const first = concert[0] ?? written[0];
  const measure = first?.measure ?? 0;
  const concertPitch = first ? pitchLabel(first) : "";
  const writtenPitchRaw = written[0] ? pitchLabel(written[0]) : null;
  const writtenPitch =
    writtenPitchRaw && writtenPitchRaw !== concertPitch ? writtenPitchRaw : null;

  const fragmentCount = Math.max(concert.length, written.length);
  const tied = concert.some((n) => n.tied) || written.some((n) => n.tied);
  const tieLabel = tied && fragmentCount > 1 ? copy.tieFragments(fragmentCount) : null;

  const durationLabel = first ? noteTypeJa(first) : "";
  const where = copy.measure(measure);
  const onsetLabel =
    onsetMs != null ? `${where}（${copy.scoreSeconds(onsetMs / 1000)}）` : where;

  return {
    kind: "note",
    canonicalId,
    measure,
    concertPitch,
    writtenPitch,
    durationLabel,
    onsetLabel,
    tieLabel,
    issues: issues.map((issue) => ({
      id: issue.id,
      reasonTitle: copy.review.reasonTitle(issue.reason),
      reasonDetail: copy.review.reasonDetail(issue),
      severityLabel: copy.review.severityLabel(issue.severity),
      statusLabel: copy.review.statusLabel(issue.status),
      confidencePct:
        issueConfidence(issue) != null
          ? Math.round((issueConfidence(issue) as number) * 100)
          : null,
    })),
  };
}

/** Pitch view the inspector prefers for its headline — the presentation the
 *  user is looking at leads; the other stays as secondary info. */
export function headlinePitch(
  model: NoteInspectorModel,
  view: PitchViewSetting,
): { primary: string; secondary: string | null } {
  if (view === "hornF" && model.writtenPitch) {
    return { primary: model.writtenPitch, secondary: model.concertPitch };
  }
  return { primary: model.concertPitch, secondary: model.writtenPitch };
}

// @vitest-environment jsdom
/**
 * ReviewSession tests (UI-050): decisions, corrections, undo/redo and the
 * revision-bound persistence contract (domain/review.py — decisions live
 * against (issue_id, score_revision) and never carry across revisions).
 */
import { describe, expect, it } from "vitest";
import { createFixtureScoreDocument } from "./fixtureDocument";
import { openIssues } from "./review";
import { ReviewSession } from "./reviewSession";
import { NO_NOTE_EDIT } from "./scoreEdits";
import { XmlScoreDocument } from "./xmlDocument";
import type { ScoreDocumentPort } from "./document";
import concertXml from "./fixtures/score_concert.musicxml?raw";
import hornXml from "./fixtures/score_horn_in_f.musicxml?raw";

describe("ReviewSession decisions", () => {
  it("accept marks the issue resolved and persists on the document", () => {
    const doc = createFixtureScoreDocument();
    const session = new ReviewSession(doc);
